<?php include 'config.php'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $e=$conn->real_escape_string($_POST['email']);$u=$conn->query("SELECT * FROM users WHERE email='$e'")->fetch_assoc(); if($u && password_verify($_POST['password'],$u['password'])){$_SESSION['user_id']=$u['user_id'];$_SESSION['full_name']=$u['full_name'];$_SESSION['role']=$u['role']; header($u['role']==='admin'?'Location: admin/admin_dashboard.php':'Location: index.php');exit;}else $error='Invalid login'; } ?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Login</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'nav.php'; ?><form class="form" method="POST"><h1>Login</h1><?php if($error)echo '<p class="alert">'.$error.'</p>'; ?><input name="email" placeholder="Email"><input name="password" type="password" placeholder="Password"><button>Login</button><p>Admin: admin@stylehub.com / 123456</p></form></body></html>